        "The Bhojeshwar Temple is an 11th-century Shiva temple at Bhojpur, about 28 km from Bhopal, Madhya Pradesh, attributed to the Paramara king Bhoja (r. c. 1010–1055). It is famous for one of the largest monolithic Shiva lingams in India — carved from a single stone and rising about 2.3 m — and for being unfinished: its shikhara was never completed and the original earthen construction ramp still stands beside it. Masons' architectural plans are engraved on the surrounding rocks. Often called the 'Somnath of the East', it is protected by the Archaeological Survey of India. MyTripMyTravel pairs it with Bhimbetka on an escorted day from Bhopal.",
