    answer: "The Thousand Pillar Temple stands at Hanamkonda, beside Warangal, and was built in 1163 under the Kakatiya king Rudradeva. Set on a star-shaped platform, it is a triple shrine — a trikutalaya — dedicated to Shiva, Vishnu and Surya, with a pillared hall famed for its rows of carved columns, a polished monolithic Nandi and finely worked stone screens. It remains a living Hindu temple in daily worship. MyTripMyTravel arranges a respectful escorted visit, with the Kakatiya carving and layout explained and the etiquette of an active shrine observed.",
