    answer: "The Amruteshwar Temple stands in the remote hill village of Ratanwadi, near Bhandardara and Arthur (Wilson) Lake in Maharashtra's Western Ghats. A stone Shiva temple in the Hemadpanti style, it is popularly held to be around a thousand years old and is admired for its finely carved black-stone exterior. Set at the base of the trek to Ratangad fort, it is an active place of worship. MyTripMyTravel arranges a guided visit combined with the Bhandardara lake country, with transport over the region's narrow hill roads.",
